		array(
			'path' => 'resources/glossary', 'title' => 'Glossary', 'excerpt' => 'Greek, Hebrew and Arabic terms used across the website.',
			'body' => array(
				'- <strong>Injīl</strong> (Arabic): the revelation given to ʿĪsā; the Qur’anic word, probably from Greek <em>euangelion</em>.',
				'- <strong>Tawrāt</strong> (Arabic): the Torah given to Mūsā.',
				'- <strong>Taḥrīf</strong> (Arabic): alteration. <em>Taḥrīf al-maʿnā</em> is alteration of meaning; <em>taḥrīf al-lafẓ</em> is alteration of the text.',
				'- <strong>Masīḥ</strong> (Arabic): Messiah; the title the Qur’an gives ʿĪsā.',
				'- <strong>Kalima</strong> (Arabic): word; used of ʿĪsā in 3:45 and 4:171.',
				'- <strong>Ḥawāriyyūn</strong> (Arabic): the disciples of ʿĪsā.',
